-- Restore the complete 18-week physiology plan from SpaceWeb data/subject_plans.json.
-- Idempotent: each row has a stable metadata.legacy_plan_key; no existing course data is deleted.
BEGIN;
WITH seed(week_no, planned_date, lecture, practice, control) AS (
  VALUES
  (1,'2026-09-07','Лек 1: Предмет и методы исследования в физиологии. Основные понятия физиологии. Физиологические свойства биологической мембраны. Роль в формировании биоэлектрических процессов.','Практика 1: Введение в предмет физиологии. Основные понятия физиологии и методы исследования.',NULL),
  (2,'2026-09-14','Лек 2: Механизмы формирования потенциала покоя и потенциала действия в возбудимых тканях.','Практика 2: Физиология клетки. Биоэлектрические явления в живых тканях. Механизмы формирования потенциала покоя и потенциала действия.',NULL),
  (3,'2026-09-21','Лек 3: Законы раздражения возбудимых структур и методы их исследования, роль в оценке уровня возбудимости.','Практика 3: Методы исследования функций возбудимых тканей. Законы раздражения возбудимых структур.',NULL),
  (4,'2026-09-28','Лек 4: Физиология мышц. Виды и характеристики двигательных единиц. Особенности гладкой мускулатуры.','Практика 4: Физиология мышечного сокращения. Характеристика моторных единиц: виды, свойства. Функциональные особенности гладкой мышечной ткани.',NULL),
  (5,'2026-10-05','Лек 5: Физиология нервной клетки. Механизм формирования потенциала действия на мембране нейрона. Особенности проведения возбуждения по нервным волокнам.','Практика 5: Физиология нервной клетки. Интегративная функция нейрона. Проведение возбуждения по нервным волокнам.',NULL),
  (6,'2026-10-12','Лек 6: Физиология нейрональной сети и нервного центра. Рефлекторный принцип организации нервной системы.','Коллоквиум по разделу «Физиология клетки. Физиология возбудимых структур». Методы исследования.','Коллоквиум по разделу «Физиология клетки. Физиология возбудимых структур». Методы исследования.'),
  (7,'2026-10-19','Лек 7: Физиология торможения в нервной системе. Механизмы координации рефлекторной деятельности.','Практика 7: Общая физиология нервной системы. Характеристика рефлекторного принципа её функционирования.',NULL),
  (8,'2026-10-26','Лек 8: Соматическая нервная система. Участие спинного мозга, ядер ствола головного мозга, мозжечка, базальных ядер и коры больших полушарий в организации моторики.','Практика 8: Частная физиология нервной системы. Соматическая нервная система. Общие принципы регуляции мышечного тонуса и движения.',NULL),
  (9,'2026-11-02','Лек 9: Физиология вегетативной нервной системы.','Практика 9: Частная физиология нервной системы. Особенности вегетативной нервной системы. Регуляция функционирования внутренних органов.',NULL),
  (10,'2026-11-09','Лек 10: Общие свойства системы крови. Физиология эритроцитов.','Коллоквиум по разделу «Физиология центральной нервной системы». Методы исследования.','Коллоквиум по разделу «Физиология центральной нервной системы». Методы исследования.'),
  (11,'2026-11-16','Лек 11: Физиология лейкоцитов. Понятие иммунитета, схема иммунного ответа.','Практика 11: Понятие о системе крови, общая характеристика её функций. Физико-химические свойства крови.',NULL),
  (12,'2026-11-23','Лек 12: Физиология тромбоцитов. Сосудисто-тромбоцитарный и коагуляционный гемостаз. Регуляция агрегатного состояния крови.','Практика 12: Физиология форменных элементов крови. Характеристика её защитных систем.',NULL),
  (13,'2026-11-30','Лек 13: Физиологические свойства сердечной мышцы. Природа автоматии сердца. Сердечный цикл.','Практика 13: Иммунобиологические свойства крови. Физиология гемостаза. Система регуляции агрегатного состояния крови.',NULL),
  (14,'2026-12-07','Лек 14: Регуляция сердечной деятельности. Периферические и центральные механизмы.','Современные методы исследования крови. Коллоквиум по разделу «Физиология крови».','Современные методы исследования крови. Коллоквиум по разделу «Физиология крови».'),
  (15,'2026-12-14','Лек 15: Физиология кровеносных сосудов. Функциональная классификация сосудистого русла. Основные законы гемодинамики.','Практика 15: Физиологические свойства сердечной мышцы. Природа автоматии сердца. Физиология сердечного цикла. Характеристика функциональных показателей деятельности сердца.',NULL),
  (16,'2026-12-21','Лек 16: Функции системы микроциркуляции. Механизмы регуляции сосудистого тонуса. Роль лимфатической системы.','Практика 16: Регуляция сердечной деятельности. Понятие сосудодвигательного центра.',NULL),
  (17,'2026-12-28','Лек 17: Методы исследования сердца и кровеносных сосудов.','Практика 17: Физиологические свойства кровеносных сосудов, регуляция сосудистого тонуса.',NULL),
  (18,'2027-01-11',NULL,'Практика 18: Клинико-физиологические методы исследования сердечной деятельности и сосудов.',NULL)
),
subject AS (
  SELECT id FROM public.subjects
  WHERE slug='physiology' AND course_number=2 AND semester=3 AND is_active=true
  ORDER BY id LIMIT 1
)
INSERT INTO public.curriculum_items
  (subject_id,course_number,semester,item_type,title,description,planned_date,order_index,is_required,is_active,source,metadata)
SELECT
  subject.id,2,3,
  CASE WHEN seed.lecture IS NULL THEN 'practice' ELSE 'lecture' END,
  COALESCE(seed.lecture,seed.practice),
  seed.practice,
  seed.planned_date::date,
  seed.week_no,
  true,true,
  'spaceweb:subject_plans.json',
  jsonb_build_object(
    'legacy_plan_key','spaceweb:physiology:week-'||lpad(seed.week_no::text,2,'0'),
    'week',seed.week_no,'lecture',seed.lecture,'practice',seed.practice,
    'control',seed.control,'study',jsonb_build_array(),
    'source_file','data/subject_plans.json','source_plan','official_plan_Sazonova_2026_2027'
  )
FROM subject CROSS JOIN seed
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_items existing
  WHERE existing.subject_id=subject.id
    AND existing.metadata->>'legacy_plan_key'='spaceweb:physiology:week-'||lpad(seed.week_no::text,2,'0')
);
COMMIT;
